gvplugin_library_t *gvplugin_library_load(GVC_t *gvc, const char *pathname) {
#ifdef ENABLE_LTDL
    lt_dlhandle hndl;
    char *s;
    size_t len;
    char *libdir;
    char *suffix = "_LTX_library";

    if (!gvc->common.demand_loading)
        return NULL;

    libdir = gvconfig_libdir(gvc);
    agxbuf fullpath = {0};
#ifdef _WIN32
    if (pathname[1] == ':') {
#else
    if (pathname[0] == '/') {
#endif
        agxbput(&fullpath, pathname);
    } else {
        agxbprint(&fullpath, "%s%c%s", libdir, PATH_SEPARATOR, pathname);
    }
    free(libdir);

    if (lt_dlinit()) {
        agerrorf("failed to init libltdl\n");
        agxbfree(&fullpath);
        return NULL;
    }
    char *p = agxbuse(&fullpath);
    hndl = lt_dlopen(p);
    if (!hndl) {
        if (access(p, R_OK) == 0) {
            agwarningf("Could not load \"%s\" - %s\n", p, "It was found, so perhaps one of its dependents was not.  Try ldd.");
        }
        else {
            agwarningf("Could not load \"%s\" - %s\n", p, lt_dlerror());
        }
        agxbfree(&fullpath);
        return NULL;
    }
    if (gvc->common.verbose >= 2)
        fprintf(stderr, "Loading %s\n", p);

    s = strrchr(p, PATH_SEPARATOR);
    len = strlen(s);
#if defined(_WIN32) && !defined(__MINGW32__) && !defined(__CYGWIN__)
    if (len < strlen("/gvplugin_x")) {
#else
    if (len < strlen("/libgvplugin_x")) {
#endif
        agerrorf("invalid plugin path \"%s\"\n", p);
        agxbfree(&fullpath);
        return NULL;
    }
#if defined(_WIN32) && !defined(__MINGW32__) && !defined(__CYGWIN__)
    const char *const no_prefix = s + 1; // strip leading “/”
#else
    const char *const no_prefix = s + 4; // strip leading “/lib” or “/cyg”
#endif
#if defined(__CYGWIN__) || defined(__MINGW32__)
    // strip trailing “-1.dll”
    const strview_t no_suffix = strview(no_prefix, '-');
#else
    // strip trailing “.so.0” or “.dll” or “.sl”
    const strview_t no_suffix = strview(no_prefix, '.');
#endif
    agxbuf sym_buf = {0};
    // append “_LTX_library”
    agxbprint(&sym_buf, "%.*s%s", (int)no_suffix.size, no_suffix.data, suffix);

    const char *const sym = agxbuse(&sym_buf);
    lt_ptr ptr = lt_dlsym(hndl, sym);
    if (!ptr) {
        agerrorf("failed to resolve %s in %s\n", sym, p);
    }
    agxbfree(&sym_buf);
    agxbfree(&fullpath);
    return ptr;
#else
    (void)gvc;
    (void)pathname;

    agerrorf("dynamic loading not available\n");
    return NULL;
#endif
}

