#ifndef _WIN32
/// `readlink`-alike but dynamically allocates
static char *readln(const char *path) {

  char *resolved = NULL;
  size_t size = 0;

  while (true) {

    // expand target buffer
    {
      char *const r = realloc(resolved, size == 0 ? 1024 : (size * 2));
      if (r == NULL) {
        // failed, out-of-memory
        free(resolved);
        return NULL;
      }
      resolved = r;
      size = size == 0 ? 1024 : (size * 2);
    }

    // attempt to resolve
    {
      const ssize_t written = readlink(path, resolved, size);
      if (written < 0) {
        break;
      }
      if ((size_t)written < size) {
        // success
        resolved[written] = '\0';
        return resolved;
      }
    }
  }

  // failed
  free(resolved);
  return NULL;
}
#endif

char *gv_find_me(void) {

  // macOS
#ifdef __APPLE__
  {
    // determine how many bytes we will need to allocate
    uint32_t buf_size = 0;
    const int rc = _NSGetExecutablePath(NULL, &buf_size);
    assert(rc != 0);
    assert(buf_size > 0);

    char *path = calloc(1, buf_size);
    if (path == NULL) {
      // failed, out-of-memory
      return NULL;
    }

    // retrieve the actual path
    if (_NSGetExecutablePath(path, &buf_size) < 0) {
      free(path);
      return NULL;
    }

    // try to resolve any levels of symlinks if possible
    while (true) {
      char *const buf = readln(path);
      if (buf == NULL)
        return path;

      free(path);
      path = buf;
    }
  }
#elif defined(_WIN32)
  {
    char *path = NULL;
    DWORD path_size = 0;
    int rc = 0;

    do {
      {
        const DWORD size = path_size == 0 ? 1024 : (path_size * 2);
        char *const p = realloc(path, size);
        if (p == NULL) {
          // failed, out-of-memory
          free(path);
          return NULL;
        }
        path = p;
        path_size = size;
      }

      rc = GetModuleFileNameA(NULL, path, path_size);
      if (rc == 0) {
        free(path);
        return NULL;
      }

    } while ((DWORD)rc == path_size);

    // the Windows APIs return '\'-separated directory components, but MinGW
    // uses '/' as the canonical directory separator, so convert these
#ifdef __MINGW32__
    for (size_t i = 0; path[i] != '\0'; ++i) {
      if (path[i] == '\\') {
        path[i] = '/';
      }
    }
#endif

    return path;
  }
#else

  // Linux, Cygwin
  char *path = readln("/proc/self/exe");
  if (path != NULL)
